import React from "react";


const Products = () => {
  const productList = [
    {
      image: "https://via.placeholder.com/120",
      name: "Wireless Headphones",
      category: "Electronics",
      price: 2999,
      brand: "Sony",
    },
    {
      image: "https://via.placeholder.com/120",
      name: "Running Shoes",
      category: "Footwear",
      price: 1999,
      brand: "Nike",
    },
  ];

  return (
    <div>
      <h1 style={{ fontSize: "large", textAlign: "center", marginTop: "40px" }}>
        PRODUCTS
      </h1>

      <div className="product-container">
        {productList.map((product, index) => (
          <div key={index} className="product-card">
            <img src={product.image} alt={product.name} className="product-img" />

            <div className="product-field">{product.name}</div>
            <div className="product-field">{product.category}</div>
            <div className="product-field">₹{product.price}</div>
            <div className="product-field">{product.brand}</div>

            <div className="product-action">
              <button className="buy-btn">Buy Now</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Products;
